*** Update File: src/range.js
@@ -5,7 +5,7 @@ export function range(start, end, step = 1) {
   const out = [];
-  for (let n = start; n < end; n += step) out.push(n);
+  for (let n = start; n <= end; n += step) out.push(n);
   return out;
}
